-- Plans. Payment is deferred (bKash later): 'pro' exists so prices live in data, but nothing charges yet.
-- AI caps are per user per calendar month, in micro-USD (1 USD = 1,000,000).
insert into public.plans (code, name, price_minor, currency, billing_interval, trial_days, ai_monthly_cap_micro_usd, features) values
  ('trial', 'Pro trial (7 days)', 0, 'BDT', 'none', 7, 500000, '{"ai": true, "matching": true, "reminders": true}'),
  ('pro', 'Job Switcher Pro', 19900, 'BDT', 'month', 0, 1000000, '{"ai": true, "matching": true, "reminders": true}'),
  ('free', 'Free (after trial)', 0, 'BDT', 'none', 0, 0, '{"ai": false, "matching": true, "reminders": true}')
on conflict (code) do update set name = excluded.name, price_minor = excluded.price_minor, trial_days = excluded.trial_days,
  ai_monthly_cap_micro_usd = excluded.ai_monthly_cap_micro_usd, features = excluded.features;
